/** Unwanted-impact diagnosis (scratch, 2026-10-30). Replays saved tracks, detects
 * line.strike.v3 events exactly as tools/eval/measure.ts does, and describes every
 * event (matched or not) physically. Writes one JSON line per event.
 *
 *   cd <worktree> && node --import tsx <scratch>/ua.ts OUT.jsonl
 *
 * Inputs: the dev and confirm panels (v-s2x100-*) and the eight Trouble rides. */
import {readFileSync, readdirSync, writeFileSync, existsSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {join} from 'node:path';
import {observe} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/tools/measure/observe.ts';
import {strikeMotionFrames, detectStrikes, accountStrikes, STRIKE_V3_CONTRACT, STRIKE_V2_CONTRACT} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/tools/measure/strike.ts';

const SCR = '/tmp/claude-1000/-home-wyss-line/897a8423-a8a8-40b1-ab25-a90f46eae018/scratchpad';
const TROUBLE = '/home/wyss/line/generated/trouble-variants-v1';
const DUR: Record<string, number> = {};
async function songDuration(song: string) {
  if (DUR[song]) return DUR[song];
  const spec = (await import(`/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/productions/${song}/spec.ts`)).default;
  return DUR[song] = Math.round(spec.duration * 40);
}

type Ride = {set: string; id: string; song: string; seed: number; pert: number | null; track: any; D: number;
  targets: Array<{frame: number; impact?: number}>; air?: Map<number, number>; ref?: {loss: number}};

async function rides(): Promise<Ride[]> {
  const out: Ride[] = [];
  for (const set of ['dev', 'confirm']) {
    const dir = join(SCR, set, 'cells');
    for (const f of readdirSync(dir).filter(f => f.endsWith('.json')).sort()) {
      const cell = JSON.parse(readFileSync(join(dir, f), 'utf8'));
      const track = JSON.parse(gunzipSync(readFileSync(join(dir, f.replace(/\.json$/, '.track.json.gz')))).toString());
      const air = new Map<number, number>(cell.gaps.filter((g: any) => g[1] === 'air').map((g: any) => [g[0], g[2]]));
      out.push({set, id: cell.case.id, song: cell.case.song, seed: cell.case.seed, pert: cell.case.perturbation, track,
        D: await songDuration(cell.case.song), targets: cell.case.targets.map((t: any) => ({frame: t.frame, impact: t.impact ?? undefined})),
        air, ref: {loss: cell.impact3.loss}});
    }
  }
  for (const d of readdirSync(TROUBLE).filter(d => /^[a-z]+-\d+$/.test(d)).sort()) {
    const p = JSON.parse(readFileSync(join(TROUBLE, d, `trouble_50s-${d.split('-')[1]}-production.json`), 'utf8'));
    const air = new Map<number, number>();
    for (const o of p.observations ?? []) if (o.axis === 'air' && o.target != null) air.set(o.gap, o.target);
    out.push({set: 'trouble', id: `trouble_50s~${d}`, song: 'trouble_50s', seed: p.seed, pert: null, track: p.track, D: p.case.durationFrames,
      targets: p.impactEvaluation.targets, air, ref: {loss: p.impactEvaluation.account.loss}});
  }
  return out;
}

const SLED = [0, 1, 2, 3], BODY = [4, 5, 6, 7], FEET = [8, 9];
export function lineRoles(track: any) {
  // Within a section (id block of 10000), lines form connected chains in id order.
  // One chain: the main rail. Two chains: main then guide (as tools/measure/hit_anatomy.ts;
  // checked against the production report's mainSegments on the Trouble rides).
  // More: fragments (chain index kept). `ceiling`: the line's solid side faces down
  // (normal (dy, −dx) for an unflipped line; flipped negates), i.e. it pushes a rider down.
  const bySec = new Map<number, any[][]>();
  for (const l of track.lines) {
    const s = Math.floor((l.id - 1000) / 10000), c = bySec.get(s) ?? [[]], prev = c.at(-1)!.at(-1);
    if (prev && (Math.abs(prev.x2 - l.x1) > 1e-6 || Math.abs(prev.y2 - l.y1) > 1e-6)) c.push([]);
    c.at(-1)!.push(l); bySec.set(s, c);
  }
  const role = new Map<number, {section: number; guide: boolean; chain: number; chains: number; ceiling: boolean; normalY: number}>();
  for (const [s, chains] of bySec) chains.forEach((c, k) => {for (const l of c) {
    const dx = l.x2 - l.x1, dy = l.y2 - l.y1, len = Math.hypot(dx, dy) || 1, ny = (l.flipped ? 1 : -1) * dx / len;
    role.set(l.id, {section: s, guide: chains.length === 2 && k === 1, chain: k, chains: chains.length, ceiling: ny > .5, normalY: ny});
  }});
  return role;
}

async function main() {
  const outPath = process.argv[2];
  const lines: string[] = [], rideRows: any[] = [];
  for (const r of await rides()) {
    const o: any = observe(r.track, r.D, r.targets);
    const mf = strikeMotionFrames(o);
    const reversalAfter = new Set<number>();
    const events = detectStrikes(mf, STRIKE_V3_CONTRACT, (_a, b) => reversalAfter.add(b.contactStart * 100000 + b.onset)).filter(e => e.onset <= r.D);
    const account = accountStrikes(events, r.targets, STRIKE_V3_CONTRACT);
    const v2events = detectStrikes(mf, STRIKE_V2_CONTRACT).filter(e => e.onset <= r.D);
    const v2acc = accountStrikes(v2events, r.targets, STRIKE_V2_CONTRACT);
    const roles = lineRoles(r.track), lineById = new Map<number, any>(r.track.lines.map((l: any) => [l.id, l]));
    const last = Math.min(r.D + 20, o.frames.length - 1);
    const V = (f: number) => {let x = 0, y = 0; for (const [a, b, c, d] of o.frames[f].points) {x += a - c; y += b - d;} return [x / 10, y / 10];};
    const phi = (f: number) => {const P = o.frames[f].points; return Math.atan2(P[2][1] - P[1][1], P[2][0] - P[1][0]) * 180 / Math.PI;};
    const contact = (f: number) => !!o.observed[f]?.[0];
    const matchOf = new Map<number, number>(account.matches.map((m: any) => [m.event, m.target]));
    const v2unmatched = new Set(v2acc.unmatchedEvents.map((i: number) => v2events[i].onset));
    const T = r.targets, M = Math.max(1, T.length);
    // previous contacted section before frame f
    const lastContactSection = (f: number) => {
      for (let g = f - 1; g >= Math.max(0, f - 400); g--) {const c = o.frames[g].collisions; if (c.length) return roles.get(c[0][0])?.section ?? -1;}
      return -1;
    };
    let prevMatched: any = null;
    events.forEach((e: any, i: number) => {
      const target = matchOf.get(i);
      // nearest beat
      let nb = 0; for (let j = 1; j < T.length; j++) if (Math.abs(T[j].frame - e.onset) < Math.abs(T[nb].frame - e.onset)) nb = j;
      let gapIdx = T.findIndex(t => t.frame > e.onset); if (gapIdx < 0) gapIdx = T.length;
      const gStart = gapIdx ? T[gapIdx - 1].frame : 0, gEnd = gapIdx < T.length ? T[gapIdx].frame : r.D;
      let flight = 0; for (let f = e.contactStart - 1; f >= 0 && !contact(f); f--) flight++;
      let eStart = e.contactStart; while (eStart > 0 && contact(eStart - 1)) eStart--;
      let eEnd = e.end; while (eEnd < last && contact(eEnd + 1)) eEnd++;
      const pts = new Set<number>(), firstPts = new Set<number>(), secs = new Set<number>(), guideHit = {main: false, guide: false};
      const lineIds = new Set<number>();
      let ceiling = false, floor = false, firstCeiling = false, fragment = false, bodyCeiling = false, sledFloor = false;
      for (let f = e.contactStart; f <= e.end; f++) for (const [id, p] of o.frames[f].collisions) {
        pts.add(p); lineIds.add(id); const ro = roles.get(id);
        if (ro) {
          secs.add(ro.section); if (ro.guide) guideHit.guide = true; else guideHit.main = true;
          if (ro.chains > 2) fragment = true;
          if (ro.ceiling) {ceiling = true; if (f === e.contactStart) firstCeiling = true; if (BODY.includes(p)) bodyCeiling = true;}
          if (ro.normalY < -.5) {floor = true; if (!BODY.includes(p)) sledFloor = true;}
        }
        if (f === e.contactStart) firstPts.add(p);
      }
      // strongest 2-frame push in the event (as the v2/v3 strength), from the half-rise onset
      let best = [0, 0, 0], at = e.onset;
      for (let a = e.onset; a <= Math.max(e.onset, e.end - 1); a++) {
        const w = [0, 0, 0]; for (let f = a; f <= Math.min(e.end, a + 1); f++) {const p = mf[f].impulse!; w[0] += p[0]; w[1] += p[1]; w[2] += p[2];}
        if (Math.hypot(...w) > Math.hypot(...best)) {best = w; at = a;}
      }
      const pushTravel = Math.hypot(best[0], best[1]), pushAngle = Math.atan2(-best[1], best[0]) * 180 / Math.PI; // 90 = straight up on screen
      const vb = V(Math.max(0, e.contactStart - 1)), va = V(Math.min(last, e.end));
      const turn = Math.abs(((Math.atan2(va[1], va[0]) - Math.atan2(vb[1], vb[0])) * 180 / Math.PI + 540) % 360 - 180);
      const prev = i ? events[i - 1] : null;
      const sectionBefore = lastContactSection(e.contactStart);
      const row = {
        set: r.set, ride: r.id, song: r.song, seed: r.seed, pert: r.pert, beats: T.length, D: r.D,
        i, kind: e.kind, reversal: reversalAfter.has(e.contactStart * 100000 + e.onset), contactStart: e.contactStart, onset: e.onset, peak: e.peakFrame, end: e.end,
        strength: e.strength, raw: e.raw, cost: (e.raw / 7.55) ** 2 / M,
        matched: target ?? null, requested: target != null ? T[target].impact ?? null : null,
        nearestBeat: nb, nearestOffset: e.onset - T[nb].frame, nearestReq: T[nb].impact ?? null, nearestBeatMatched: account.matches.some((m: any) => m.target === nb),
        gapIdx, gapStart: gStart, gapEnd: gEnd, gapLen: gEnd - gStart, gapAir: r.air?.get(gapIdx) ?? null,
        prevBeatReq: gapIdx ? T[gapIdx - 1].impact ?? null : null, nextBeatReq: gapIdx < T.length ? T[gapIdx].impact ?? null : null,
        sincePrevEvent: prev ? e.onset - prev.onset : null, prevStrength: prev?.strength ?? null, prevMatched: prev ? matchOf.has(i - 1) : null,
        sinceMatched: prevMatched ? e.onset - prevMatched.onset : null, matchedStrengthBefore: prevMatched?.strength ?? null,
        flightBefore: flight, engagementStart: eStart, engagementLen: eEnd - eStart + 1,
        points: [...pts].sort(), firstPoints: [...firstPts].sort(),
        sled: [...pts].some(p => SLED.includes(p)), body: [...pts].some(p => BODY.includes(p)), feet: [...pts].some(p => FEET.includes(p)),
        bodyOnly: pts.size > 0 && [...pts].every(p => BODY.includes(p)),
        sections: [...secs].sort((a, b) => a - b), sectionBefore, main: guideHit.main, guide: guideHit.guide, lines: lineIds.size,
        ceiling, floor, firstCeiling, fragment, bodyCeiling, sledFloor,
        push: best.map(x => +x.toFixed(3)), pushTravel, pushAngle, spinShare: Math.hypot(...best) ? Math.abs(best[2]) / Math.hypot(...best) : 0, pushAt: at,
        vBefore: vb.map(x => +x.toFixed(3)), vAfter: va.map(x => +x.toFixed(3)), speedBefore: Math.hypot(vb[0], vb[1]), speedAfter: Math.hypot(va[0], va[1]), turn,
        phi: phi(e.contactStart), inverted: Math.abs(phi(e.contactStart)) > 90,
        v2extra: v2unmatched.has(e.onset),
      };
      lines.push(JSON.stringify(row));
      if (target != null) prevMatched = e;
    });
    // Under-count check: contacted frames outside every event's own frames
    // [contactStart, end], and inside matched events the frames after the peak
    // whose push is opposite to the peak push but below the split floor. For each,
    // the 2-frame whole-body change (the v2/v3 strength formula), at local maxima.
    const covered = new Map<number, number>();
    events.forEach((e: any, i: number) => {for (let f = e.contactStart; f <= e.end; f++) covered.set(f, i);});
    const w2 = (f: number) => {const p = mf[f].impulse!, q = mf[f + 1]?.impulse ?? [0, 0, 0]; return Math.hypot(p[0] + q[0], p[1] + q[1], p[2] + q[2]) / 7.55;};
    for (let f = 1; f < Math.min(r.D, mf.length - 1); f++) {
      if (!contact(f)) continue;
      const s = w2(f);
      if (s < .05 || s < w2(f - 1) || s <= w2(f + 1)) continue;
      const ev = covered.get(f);
      const kind = ev === undefined ? 'uncovered' : 'inside';
      if (kind === 'inside') {
        // inside an event: only report a push opposite (>90°) to that event's peak push, after the peak
        const e = events[ev!]; if (f <= e.peakFrame) continue;
        const a = mf[e.peakFrame].impulse!, b = mf[f].impulse!;
        if (a[0] * b[0] + a[1] * b[1] >= 0) continue;
      }
      const ids = o.frames[f].collisions;
      let nb = 0; for (let j = 1; j < T.length; j++) if (Math.abs(T[j].frame - f) < Math.abs(T[nb].frame - f)) nb = j;
      const Sm = (k: number) => .25 * mf[k - 1].J + .5 * mf[k].J + .25 * mf[k + 1].J;
      let minBefore = Infinity, runBefore = 0;
      for (let k = f - 1; k >= Math.max(1, f - 8) && contact(k); k--) {minBefore = Math.min(minBefore, Sm(k)); runBefore++;}
      lines.push(JSON.stringify({hidden: true, set: r.set, ride: r.id, pert: r.pert, frame: f, kind, inMatched: ev !== undefined && matchOf.has(ev), strength: s,
        S: Sm(f), valley: Number.isFinite(minBefore) ? minBefore / Sm(f) : 0, runBefore,
        push: mf[f].impulse, ceiling: ids.some(([id]: number[]) => roles.get(id)?.ceiling), body: ids.some(([, p]: number[]) => BODY.includes(p)),
        bodyOnly: ids.length > 0 && ids.every(([, p]: number[]) => BODY.includes(p)), guide: ids.some(([id]: number[]) => roles.get(id)?.guide),
        nearestOffset: f - T[nb].frame, nearestReq: T[nb].impact ?? null}));
    }
    const loss = account.loss;
    rideRows.push({set: r.set, ride: r.id, loss, refLoss: r.ref?.loss, beats: T.length, events: events.length, unmatched: account.unmatchedEvents.length,
      extraMse: account.extraMse, strengthMse: account.strengthMse, timingMse: account.timingMse, missing: account.missingTargets.length, complete: account.complete,
      lastFrame: o.frames.length - 1});
    console.error(`${r.set} ${r.id} events ${events.length} unmatched ${account.unmatchedEvents.length} loss ${loss.toFixed(5)} ref ${r.ref?.loss.toFixed(5)}`);
  }
  writeFileSync(outPath, lines.join('\n') + '\n');
  writeFileSync(outPath.replace(/\.jsonl$/, '-rides.json'), JSON.stringify(rideRows, null, 1));
  process.exit(0);
}
await main();

