/** Under-count audit of line.strike.v3 identity (scratch, 2026-10-30).
 * Replays the detector's walk (same arithmetic as scripts/lib/strike_impact.ts
 * detectStrikes) and records every force maximum (smoothed J >= floor) whose frame
 * lies after the last frame of the event it was folded into — i.e. a push the
 * account never measures. Reason: 'window' (a renewal whose own frames end before
 * its peak), 'rising' (no trough after the event's peak: force only rose since the
 * touchdown), 'spacing' (< 4 frames after the peak), 'valley' (no valley <= 0.5).
 * Strength: the v2/v3 formula (largest 2-frame whole-body change) over i−2..i+3.
 *   node --import tsx missed.ts OUT.jsonl */
import {readFileSync, readdirSync, writeFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {join} from 'node:path';
import {observe} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/tools/measure/observe.ts';
import {strikeMotionFrames, detectStrikes, accountStrikes, STRIKE_V3_CONTRACT as C} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/tools/measure/strike.ts';

const SCR = '/tmp/claude-1000/-home-wyss-line/897a8423-a8a8-40b1-ab25-a90f46eae018/scratchpad';
const rides: any[] = [];
for (const set of ['dev', 'confirm']) for (const f of readdirSync(join(SCR, set, 'cells')).filter(f => f.endsWith('.json')).sort()) {
  const cell = JSON.parse(readFileSync(join(SCR, set, 'cells', f), 'utf8'));
  const spec = (await import(`/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/productions/${cell.case.song}/spec.ts`)).default;
  rides.push({set, id: cell.case.id, pert: cell.case.perturbation, D: Math.round(spec.duration * 40), targets: cell.case.targets.map((t: any) => ({frame: t.frame, impact: t.impact ?? undefined})),
    track: JSON.parse(gunzipSync(readFileSync(join(SCR, set, 'cells', f.replace(/\.json$/, '.track.json.gz')))).toString())});
}
for (const d of readdirSync('/home/wyss/line/generated/trouble-variants-v1').filter(d => /^[a-z]+-\d+$/.test(d))) {
  const p = JSON.parse(readFileSync(`/home/wyss/line/generated/trouble-variants-v1/${d}/trouble_50s-${d.split('-')[1]}-production.json`, 'utf8'));
  rides.push({set: 'trouble', id: `trouble_50s~${d}`, pert: null, D: p.case.durationFrames, targets: p.impactEvaluation.targets, track: p.track});
}
const out: string[] = [];
for (const r of rides) {
  const o: any = observe(r.track, r.D, r.targets), frames = strikeMotionFrames(o);
  const events = detectStrikes(frames, C).filter(e => e.onset <= r.D), acc = accountStrikes(events, r.targets, C);
  const T = r.targets;
  for (let first = 0; first < frames.length;) {
    if (!frames[first].contact) {first++; continue;}
    let last = first; while (last + 1 < frames.length && frames[last + 1].contact) last++;
    const S = (i: number) => .25 * frames[Math.max(first, i - 1)].J + .5 * frames[i].J + .25 * frames[Math.min(last, i + 1)].J;
    let peak = first;
    const push = (i: number) => frames[i].impulse!;
    const strength = (i: number) => {let best = 0; for (let a = Math.max(first, i - 2); a <= Math.min(last, i + 3) - 1; a++) {
      const p = push(a), q = push(a + 1); best = Math.max(best, Math.hypot(p[0] + q[0], p[1] + q[1], p[2] + q[2]));} return Math.min(1, best / C.veryStrong);};
    const record = (i: number, reason: string) => {
      const f = frames[i].frame; if (f > r.D) return;
      // the event whose own frames contain f, else the event it was folded into
      const holder = events.findIndex(e => e.contactStart <= f && f <= e.end);
      if (holder >= 0) return;   // measured by an event (possibly as part of it)
      const owner = [...events.keys()].filter(k => events[k].contactStart <= f).at(-1);
      const e = owner === undefined ? undefined : events[owner], m = owner === undefined ? undefined : acc.matches.find((m: any) => m.event === owner);
      let nb = 0; for (let j = 1; j < T.length; j++) if (Math.abs(T[j].frame - f) < Math.abs(T[nb].frame - f)) nb = j;
      const ids = o.frames[f].collisions;
      out.push(JSON.stringify({set: r.set, ride: r.id, pert: r.pert, frame: f, reason, S: S(i), strength: strength(i),
        owner: owner ?? null, ownerStrength: e?.strength ?? null, ownerEnd: e?.end ?? null, ownerMatched: m ? m.target : null, ownerRequested: m ? T[m.target].impact ?? null : null,
        lag: e ? f - e.contactStart : null, nearestOffset: f - T[nb].frame, nearestReq: T[nb].impact ?? null,
        body: ids.some(([, p]: number[]) => p >= 4 && p <= 7)}));
    };
    for (let i = first + 1; i <= last; i++) {
      const a = push(peak), b = push(i), na = Math.hypot(a[0], a[1]), nb = Math.hypot(b[0], b[1]);
      if (na >= C.floor && nb >= C.floor && (a[0] * b[0] + a[1] * b[1]) / (na * nb) < C.reversalCos) {peak = i; continue;}
      const value = S(i);
      if (!(value >= S(i - 1) && (i === last || value > S(i + 1)))) continue;
      let trough = peak; for (let k = peak + 1; k < i; k++) if (S(k) < S(trough)) trough = k;
      if (value >= C.floor && i - peak >= C.spacing && trough > peak && S(trough) <= C.valley * value) {
        let start = i; while (start > trough + 1 && S(start - 1) > S(trough)) start--;
        if (i - start >= C.window) record(i, 'window');
        peak = i;
      } else {
        if (value >= C.floor) record(i, i - peak < C.spacing ? 'spacing' : trough === peak ? 'rising' : 'valley');
        if (value > S(peak)) peak = i;
      }
    }
    first = last + 1;
  }
}
writeFileSync(process.argv[2], out.join('\n') + '\n');
console.log(out.length, 'unmeasured force maxima');
process.exit(0);

