/** Where, after a matched touchdown, does the engagement's largest force fall?
 * For each matched event: the lag (frames after contact start) of the maximum
 * smoothed contact force S within the same continuous engagement, up to 15 frames,
 * and the v2/v3 2-frame change there. Split by requested level. Panel only.
 *   node --import tsx lag.ts OUT.jsonl */
import {readFileSync, readdirSync, writeFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {join} from 'node:path';
import {observe} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/tools/measure/observe.ts';
import {strikeMotionFrames, detectStrikes, accountStrikes, STRIKE_V3_CONTRACT as C} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/tools/measure/strike.ts';
const SCR = '/tmp/claude-1000/-home-wyss-line/897a8423-a8a8-40b1-ab25-a90f46eae018/scratchpad';
const out: string[] = [];
for (const set of ['dev', 'confirm']) for (const f of readdirSync(join(SCR, set, 'cells')).filter(f => f.endsWith('.json')).sort()) {
  const cell = JSON.parse(readFileSync(join(SCR, set, 'cells', f), 'utf8'));
  const spec = (await import(`/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/productions/${cell.case.song}/spec.ts`)).default;
  const D = Math.round(spec.duration * 40), targets = cell.case.targets.map((t: any) => ({frame: t.frame, impact: t.impact ?? undefined}));
  const track = JSON.parse(gunzipSync(readFileSync(join(SCR, set, 'cells', f.replace(/\.json$/, '.track.json.gz')))).toString());
  const o: any = observe(track, D, targets), fr = strikeMotionFrames(o);
  const events = detectStrikes(fr, C).filter(e => e.onset <= D), acc = accountStrikes(events, targets, C);
  for (const m of acc.matches) {
    const e = events[m.event]; if (e.kind !== 'touchdown') continue;
    let last = e.contactStart; while (last + 1 < fr.length && fr[last + 1].contact && last + 1 - e.contactStart <= 15) last++;
    const S = (i: number) => .25 * fr[Math.max(e.contactStart, i - 1)].J + .5 * fr[i].J + .25 * fr[Math.min(last, i + 1)].J;
    let best = e.contactStart; for (let i = e.contactStart; i <= last; i++) if (S(i) > S(best)) best = i;
    let w = 0; for (let a = Math.max(e.contactStart, best - 1); a <= Math.min(last - 1, best); a++) {const p = fr[a].impulse!, q = fr[a + 1].impulse!; w = Math.max(w, Math.hypot(p[0] + q[0], p[1] + q[1], p[2] + q[2]));}
    out.push(JSON.stringify({set, ride: cell.case.id, requested: targets[m.target].impact ?? null, strength: e.strength, lag: best - e.contactStart, S: S(best), change: w / C.veryStrong, contactRun: last - e.contactStart + 1}));
  }
}
writeFileSync(process.argv[2], out.join('\n') + '\n');
process.exit(0);

