import {resolveCase} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/tools/eval/inputs.ts';
import {normalizeCompilerTimeline} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/scripts/v0/optimizer/compiler_input.ts';
import {planIntentionalRepertoire} from '/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/scripts/v0/optimizer/intentional_repertoire.ts';
const SCR = '/tmp/claude-1000/-home-wyss-line/897a8423-a8a8-40b1-ab25-a90f46eae018/scratchpad';
const out: Record<string, any> = {};
for (const set of ['dev', 'confirm']) {
  const run = JSON.parse(readFileSync(`${SCR}/${set}/run.json`, 'utf8'));
  for (const c of run.panel) {
    const {spec, music, planned} = await resolveCase({id: c.id, song: c.song, seed: c.seed, perturbation: c.perturbation}, run.jolt);
    if (JSON.stringify((planned as any).targets) !== JSON.stringify(c.targets)) throw new Error(`targets differ for ${c.id}`);
    if (JSON.stringify(planned) !== JSON.stringify(c)) console.error(`note: ${c.id} resolved input identity differs (targets identical)`);
    const boundaries = music.phases.map((p: any) => p.t0 ?? p.t ?? p.start).filter(Number.isFinite);
