let track: any, targets: any[], D: number;
if (set === 'trouble') {
  const d = id.split('~')[1], p = JSON.parse(readFileSync(`/home/wyss/line/generated/trouble-variants-v1/${d}/trouble_50s-${d.split('-')[1]}-production.json`, 'utf8'));
  track = p.track; targets = p.impactEvaluation.targets; D = p.case.durationFrames;
} else {
  const dir = join(SCR, set, 'cells'), cell = JSON.parse(readFileSync(join(dir, id + '.json'), 'utf8'));
  track = JSON.parse(gunzipSync(readFileSync(join(dir, id + '.track.json.gz'))).toString());
