  const spec = (await import(`/home/wyss/line/.claude/worktrees/agent-a0d2427e85c56922c/productions/${cell.case.song}/spec.ts`)).default;
  D = Math.round(spec.duration * 40);
}
const o: any = observe(track, D, targets), mf = strikeMotionFrames(o);
const events = detectStrikes(mf, STRIKE_V3_CONTRACT).filter(e => e.onset <= D), acc = accountStrikes(events, targets, STRIKE_V3_CONTRACT);
const role = new Map<number, string>(), seen = new Map<number, {last: number; j: boolean}>();
for (const l of track.lines) {
  const s = Math.floor((l.id - 1000) / 10000), st = seen.get(s);
  if (!st) {seen.set(s, {last: l.id, j: false}); role.set(l.id, `s${s}m`); continue;}
  if (l.id !== st.last + 1) st.j = true; st.last = l.id; role.set(l.id, `s${s}${st.j ? 'g' : 'm'}`);
}
const lines = new Map<number, any>(track.lines.map((l: any) => [l.id, l]));
const short = ['PEG', 'TAIL', 'NOSE', 'STR', 'BUTT', 'SHLD', 'RH', 'LH', 'LF', 'RF'];
