for (const [i, e] of events.entries()) if (e.end >= from && e.contactStart <= to) {
  const m = acc.matches.find((m: any) => m.event === i);
  console.log(`event ${i} ${e.kind} contact ${e.contactStart} onset ${e.onset} peak ${e.peakFrame} end ${e.end} strength ${e.strength.toFixed(3)} ${m ? `MATCHED beat ${m.target}` : 'UNMATCHED'}`);
}
console.log('frame  com(x,y)        v(x,y)        |v|   push(x,y,spin)        J     phi   contacts');
for (let f = from; f <= to; f++) {
  const P = o.frames[f].points; let cx = 0, cy = 0, vx = 0, vy = 0;
  for (const [x, y, px, py] of P) {cx += x; cy += y; vx += x - px; vy += y - py;}
  cx /= 10; cy /= 10; vx /= 10; vy /= 10;
  const phi = Math.atan2(P[2][1] - P[1][1], P[2][0] - P[1][0]) * 180 / Math.PI;
  const c = o.frames[f].collisions.map(([lid, p]: number[]) => {
    const l = lines.get(lid), ang = Math.atan2(l.y2 - l.y1, l.x2 - l.x1) * 180 / Math.PI;
    return `${short[p]}@${role.get(lid)}(${ang.toFixed(0)}°${l.flipped ? 'F' : ''})`;
  });
  const im = mf[f].impulse!;
  process.stdout.write(`${mf[f].contact ? 'c' : ' '}`);
  console.log(`${String(f).padStart(5)} ${(cx.toFixed(1) + ',' + cy.toFixed(1)).padStart(15)} ${(vx.toFixed(2) + ',' + vy.toFixed(2)).padStart(13)} ${Math.hypot(vx, vy).toFixed(2).padStart(5)} ${(im[0].toFixed(2) + ',' + im[1].toFixed(2) + ',' + im[2].toFixed(2)).padStart(20)} ${mf[f].J.toFixed(2).padStart(5)} ${phi.toFixed(0).padStart(5)}  ${[...new Set(c)].join(' ')}${o.frames[f].mounted ? '' : ' UNMOUNTED'}`);
}
