import json,collections,os,sys
os.chdir(os.path.dirname(os.path.abspath(__file__)))
E=[x for x in (json.loads(l) for l in open('events.jsonl')) if not x.get('hidden')]
TH=float(sys.argv[1]) if len(sys.argv)>1 else 0.1
def panel(e): return e['set']!='trouble'
def down(e): return e['push'][1]>0.3*max(1e-9,e['pushTravel'])
def classify(e):
    """Mutually exclusive mechanism class, first match wins."""
    if e['reversal']: return 'A opposite-push split (v3)'
    if down(e) and e['ceiling']:
        return 'B1 roof: body on guide' if e['guide'] and e['bodyCeiling'] else 'B2 roof: body on upper/single rail' if e['bodyCeiling'] else 'B3 roof: sled on a ceiling'
    if e['kind']=='strike': return 'E renewal within contact'
    if e['flightBefore']<=3: return 'C floor re-landing after <=3 f hop'
    return 'D floor touchdown after flight'
def situation(e):
    s=[]
    if abs(e['nearestOffset'])<=8: s.append('within 8 f of a beat')
    if e['gapLen']>=40: s.append('gap >= 1 s')
    if e['gapLen']<16: s.append('gap < 16 f')
    if e['sinceMatched'] is not None and e['sinceMatched']<=12 and (e['matchedStrengthBefore'] or 0)>=0.5: s.append('<=12 f after a matched hit >=0.5')
    if e['guide']: s.append('guide contact')
    if e['fragment']: s.append('fragment contact')
    if e['body']: s.append('body point contact')
    if e['bodyOnly']: s.append('body only')
    if len(e['sections'])>1 or (e['sectionBefore']>=0 and e['sections'] and e['sections'][0]!=e['sectionBefore']): s.append('new section')
    if e['ceiling']: s.append('ceiling line')
    if e['vBefore'][1]<0: s.append('rising at contact')
    if e['inverted']: s.append('inverted at contact')
    return s
GR=[('panel authored',lambda e:panel(e) and e['pert'] is None),('panel perturbed',lambda e:panel(e) and e['pert'] is not None),('trouble (7 complete rides)',lambda e:e['set']=='trouble' and e['ride']!='trouble_50s~pulse-101')]
for name,f in GR:
    un=[e for e in E if f(e) and e['matched'] is None]
    ma=[e for e in E if f(e) and e['matched'] is not None]
    rides=len(set(e['set']+e['ride'] for e in E if f(e)))
    for lab,sub in [('all extras',un),(f'extras >= {TH}',[e for e in un if e['strength']>=TH])]:
        print(f'== {name}: {lab}: n={len(sub)} ({len(sub)/rides:.1f}/ride), share of extra cost {sum(e["cost"] for e in sub)/max(1e-12,sum(e["cost"] for e in un)):.2f}')
        c=collections.Counter(classify(e) for e in sub); cc=collections.defaultdict(float)
        for e in sub: cc[classify(e)]+=e['cost']
        tc=sum(cc.values())
        for k in sorted(c): v=c[k]; print(f'   {k:40s} {v:5d} {v/len(sub):5.0%}  cost {cc[k]/tc:5.0%}  median str {sorted(x["strength"] for x in sub if classify(x)==k)[v//2]:.3f}')
        s=collections.Counter(x for e in sub for x in situation(e))
        print('   situations (overlapping):', ', '.join(f'{k} {v/len(sub):.0%}' for k,v in s.most_common()))
    s=collections.Counter(x for e in ma for x in situation(e))
    print('   [matched hits, for comparison]:', ', '.join(f'{k} {v/len(ma):.0%}' for k,v in s.most_common()))
    print('   [matched hits by class]:', collections.Counter(classify(e) for e in ma).most_common())
